public record BlogViews(int BlogId, int TotalViews);

public static class BlogQueries
{
    public static async Task<IReadOnlyList<BlogViews>> GetViewsPerBlogAsync(
        BlogContext context,
        string searchTerm,
        CancellationToken cancellationToken)
    {
        var query =
            from post in context.Posts
            where post.Title.Contains(searchTerm)
            group post by post.BlogId into g
            select new BlogViews(g.Key, g.Sum(p => p.Views));

        return await query.ToListAsync(cancellationToken);
    }
}
