```csharp
public static async Task<Dictionary<int, int>> GetTotalViewsByBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken = default)
{
    var totalsQuery =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogGroup
        select new { BlogId = blogGroup.Key, TotalViews = blogGroup.Sum(post => post.Views) };

    var totals = await totalsQuery.ToListAsync(cancellationToken);

    return totals.ToDictionary(total => total.BlogId, total => total.TotalViews);
}
```

